import express from 'express';
import bodyParser from 'body-parser';
import sqlite3 from 'sqlite3';

const app = express();
const db = new sqlite3.Database('/tmp/tickets.sqlite');

app.use(bodyParser.json());

app.get('/api/tickets', (req, res) => {
    db.all('SELECT * FROM tickets ORDER BY id ASC', (err, rows) => {
        if (err) {
            res.status(500).json({ error: err.message });
        } else {
            const items = rows.map(row => ({ id: row.id, title: row.title, status: row.status, version: row.version }));
            res.json({ items });
        }
    });
});

app.post('/api/tickets', (req, res) => {
    const { id, title } = req.body;
    if (!id || !title) {
        res.status(400).json({ error: 'invalid' });
    } else if (id.length < 1 || id.length > 40 || !/^[a-zA-Z0-9_-]+$/.test(id)) {
        res.status(400).json({ error: 'invalid' });
    } else {
        db.get('SELECT * FROM tickets WHERE id = ?', [id], (err, row) => {
            if (err) {
                res.status(500).json({ error: err.message });
            } else if (row) {
                res.status(409).json({ error: 'duplicate' });
            } else {
                db.run('INSERT INTO tickets (id, title, status, version) VALUES (?, ?, ?, ?)', [id, title.trim(), 'open', 1], function(err) {
                    if (err) {
                        res.status(500).json({ error: err.message });
                    } else {
                        res.status(201).json({ item: { id, title: title.trim(), status: 'open', version: 1 } });
                    }
                });
            }
        });
    }
});

app.patch('/api/tickets/:id', (req, res) => {
    const { id } = req.params;
    const { title, status, version } = req.body;
    if (!title || !status || !version) {
        res.status(400).json({ error: 'invalid' });
    } else if (status !== 'open' && status !== 'closed') {
        res.status(400).json({ error: 'invalid' });
    } else if (!Number.isInteger(version) || version <= 0) {
        res.status(400).json({ error: 'invalid' });
    } else {
        db.get('SELECT * FROM tickets WHERE id = ?', [id], (err, row) => {
            if (err) {
                res.status(500).json({ error: err.message });
            } else if (!row) {
                res.status(404).json({ error: 'not_found' });
            } else if (row.version !== version) {
                res.status(409).json({ error: 'version_conflict' });
            } else {
                db.run('UPDATE tickets SET title = ?, status = ?, version = ? WHERE id = ?', [title.trim(), status, row.version + 1, id], function(err) {
                    if (err) {
                        res.status(500).json({ error: err.message });
                    } else {
                        res.status(200).json({ item: { id, title: title.trim(), status, version: row.version + 1 } });
                    }
                });
            }
        });
    }
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});

// Initialize database
app.get('/api/init', (req, res) => {
    db.serialize(() => {
        db.run('CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, title TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL)');
        res.status(200).json({ message: 'Database initialized' });
    });
});

export default app;

