const sqlite3 = require('sqlite3').verbose();
const express = require('express');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

const db = new sqlite3.Database('/tmp/tickets.sqlite');

// إنشاء جدول tickets إذا لم يكن موجودًا
db.serialize(() => {
  db.run("CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, title TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL)");
});

// GET /api/tickets
app.get('/api/tickets', (req, res) => {
  db.all("SELECT * FROM tickets ORDER BY id ASC", [], (err, rows) => {
    if (err) {
      res.status(500).json({ error: err.message });
      return;
    }
    res.json({ items: rows });
  });
});

// POST /api/tickets
app.post('/api/tickets', (req, res) => {
  const { id, title } = req.body;
  if (!id || !title) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (id.length < 1 || id.length > 40 || !/^[a-zA-Z0-9_-]+$/.test(id)) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (!title.trim()) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  db.run("INSERT INTO tickets (id, title, status, version) VALUES (?, ?, 'open', 1)", [id, title], function(err) {
    if (err) {
      if (err.message.includes('UNIQUE constraint failed')) {
        res.status(409).json({ error: 'duplicate' });
      } else {
        res.status(500).json({ error: err.message });
      }
      return;
    }
    res.status(201).json({ item: { id, title, status: 'open', version: 1 } });
  });
});

// PATCH /api/tickets/<id>
app.patch('/api/tickets/:id', (req, res) => {
  const { id } = req.params;
  const { title, status, version } = req.body;
  if (!title && !status) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (title && (!title.trim() || !/^[a-zA-Z0-9_-]+$/.test(title))) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (status && (status !== 'open' && status !== 'closed')) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (!Number.isInteger(version) || version <= 0) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  db.get("SELECT * FROM tickets WHERE id = ?", [id], (err, row) => {
    if (err) {
      res.status(500).json({ error: err.message });
      return;
    }
    if (!row) {
      res.status(404).json({ error: 'not_found' });
      return;
    }
    if (row.version !== version) {
      res.status(409).json({ error: 'version_conflict' });
      return;
    }
    const updates = [];
    if (title) {
      updates.push(`title = '${title.trim()}'`);
    }
    if (status) {
      updates.push(`status = '${status}'`);
    }
    updates.push(`version = version + 1`);
    const updateQuery = `UPDATE tickets SET ${updates.join(', ')} WHERE id = ?`;
    db.run(updateQuery, [id], function(err) {
      if (err) {
        res.status(500).json({ error: err.message });
        return;
      }
      db.get("SELECT * FROM tickets WHERE id = ?", [id], (err, updatedRow) => {
        if (err) {
          res.status(500).json({ error: err.message });
          return;
        }
        res.status(200).json({ item: updatedRow });
      });
    });
  });
});

// تشغيل الخادم على 127.0.0.1:3000
app.listen(3000, () => {
  console.log('Server is running on http://127.0.0.1:3000');
});

